  const ux = x + wx, uy = y + wy;
  const s = [];
  for (let i = 0; i < 5; i++) {
    const a = t * (0.3 + i * 0.12) + i * 1.2566;
    s.push([240 + Math.sin(a) * (80 + i * 20) + Math.cos(t * (0.2 + i * 0.05)) * 40, 120 + Math.cos(a * 0.7) * (48 + i * 12) + Math.sin(t * (0.25 + i * 0.07)) * 30]);
  }
  const freqs = [0.07, 0.09, 0.065, 0.08, 0.075];
  const speeds = [2.0, 1.7, 2.3, 1.9, 2.1];
  const waves = s.map((p, i) => Math.sin(Math.sqrt((ux - p[0]) ** 2 + (uy - p[1]) ** 2) * freqs[i] - t * speeds[i]));
  const act1 = (waves[0] + waves[1] + waves[2]) / 3;
  const act2 = (waves[2] + waves[3] + waves[4]) / 3;
  const inh = (Math.sin(ux * 0.04 + uy * 0.03 + t * 0.8) + Math.sin(ux * 0.03 - uy * 0.05 + t * 1.1)) / 2;
  const cross = Math.sin((act1 - act2) * 3 + t * 0.5) * 0.3;
