  const fine2 = Math.sin((ux - uy) * 0.12 - t * 2.5) * 0.12;
  const reaction = act1 * 0.5 + act2 * 0.3 - inh * 0.7 + cross + fine1 + fine2;
  const spot = Math.tanh(reaction * 2.5);
  const dx = ux - 240, dy = uy - 120, dist = Math.sqrt(dx * dx + dy * dy), ang = Math.atan2(dy, dx);
