  const radial = Math.sin(dist * 0.04 - t * 1.5);
  const angular = Math.sin(ang * 6 + t * 0.4);
  const pattern2 = Math.tanh((radial + angular * 0.4 + spiral * 0.3) * 2);
  const wx2 = Math.sin(uy * 0.02 + t * 0.5) * 15;
  const pattern3 = Math.sin((ux + wx2) * 0.08 + (uy - wx2) * 0.06 + t * 1.8);
